CREATE INDEX records_kind ON records(kind);
CREATE INDEX annotations_book ON records(book_id,kind);
CREATE INDEX memberships_book ON memberships(book_id,collection_id);
CREATE INDEX memberships_order ON memberships(collection_id,added);
CREATE INDEX locations_path ON locations(path);
CREATE UNIQUE INDEX locations_preferred ON locations(book_id) WHERE preferred=1;
CREATE INDEX recent_opened ON recent_resources(opened DESC);
CREATE TRIGGER record_kind_immutable BEFORE UPDATE OF kind ON records WHEN old.kind != new.kind BEGIN SELECT RAISE(ABORT,'Entity kind cannot change'); END;
CREATE TRIGGER annotation_book_insert BEFORE INSERT ON records WHEN new.kind='annotation' AND NOT EXISTS(SELECT 1 FROM records WHERE id=new.book_id AND kind='book') BEGIN SELECT RAISE(ABORT,'Annotation book absent'); END;
CREATE TRIGGER annotation_book_update BEFORE UPDATE ON records WHEN new.kind='annotation' AND NOT EXISTS(SELECT 1 FROM records WHERE id=new.book_id AND kind='book') BEGIN SELECT RAISE(ABORT,'Annotation book absent'); END;
CREATE TRIGGER recent_target BEFORE INSERT ON recent_resources WHEN (new.kind='book' AND NOT EXISTS(SELECT 1 FROM records WHERE id=new.resource_id AND kind='book')) OR (new.kind='collection' AND NOT EXISTS(SELECT 1 FROM collections WHERE id=new.resource_id)) BEGIN SELECT RAISE(ABORT,'Recent resource absent'); END;
CREATE TRIGGER membership_book BEFORE INSERT ON memberships WHEN NOT EXISTS(SELECT 1 FROM records WHERE id=new.book_id AND kind='book') BEGIN SELECT RAISE(ABORT,'Membership book absent'); END;
CREATE TRIGGER location_book BEFORE INSERT ON locations WHEN NOT EXISTS(SELECT 1 FROM records WHERE id=new.book_id AND kind='book') BEGIN SELECT RAISE(ABORT,'Location book absent'); END;
COMMIT;
